function compraNoHabitualCtrl($scope,commonSvc,mS,tS,modalSvc,nombreModal){const{MODAL_FILE_PATH:MODAL_FILE_PATH}=nombreModal.compra_no_habitual,{MODAL_NUEVO:MODAL_NUEVO,MODAL_EDITAR:MODAL_EDITAR,MODAL_DETALLED:MODAL_DETALLED}=nombreModal.compra_no_habitual;$scope.dataSearch={},$scope.openModal=({controller:controller,template:template,params:params,isRenderRazorPartial:isRenderRazorPartial})=>{let modalRef;modalSvc.openModalCustom({controller:controller,template:template,params:params,size:"xl",windowClass:"uibModalFullScreen",isRenderRazorPartial:isRenderRazorPartial}).result.then(result=>{"object"==typeof result&&$scope.getComprasNoHabitual()})},$scope.openModalNew=async()=>{console.log(MODAL_FILE_PATH);let modalParms={controller:(await import("./../../"+MODAL_FILE_PATH))[MODAL_NUEVO.controller],template:MODAL_NUEVO.template,params:{data:{}},isRenderRazorPartial:!0};$scope.openModal(modalParms)},$scope.getComprasNoHabitual=()=>{try{showLoader(),$scope.comprasNoHabitual=[],mS.getData("get","CompraNoHabitual/Get/"+JSON.stringify($scope.dataSearch)).then(response=>{"0"===response.code&&(console.log(response),hideLoader()),"1"===response.code&&($scope.comprasNoHabitual=JSON.parse(response.payload)||[],hideLoader())})}catch(error){$scope.comprasNoHabitual=[],console.log(error)}},$scope.initiload=()=>{try{commonSvc.getEstabAsign().then(response=>{$scope.establecimientos=response;let codEstab=$scope.establecimientos.length>0?$scope.establecimientos[0].codEstab:0;$scope.dataSearch.codEstab=codEstab,$scope.getComprasNoHabitual()})}catch(error){console.log(error)}}}app.controller("compraNoHabitualCtrl",compraNoHabitualCtrl),compraNoHabitualCtrl.$inject=["$scope","commonService","mainService","toastService","modalService","nombreModal"];